<div class="page-heading"><div><span class="eyebrow">GESTÃO DA REDE</span><h1>Pessoas e unidades</h1><p>Organize os cadastros e mantenha cada pessoa conectada à sua unidade.</p></div><a href="#person-form" class="btn btn-primary">Novo cadastro <i class="bi bi-plus-lg ms-2"></i></a></div>
<div class="card mb-4"><div class="card-header d-flex flex-wrap justify-content-between align-items-center gap-3"><strong>Alunos e equipe</strong><form method="get" class="d-flex gap-2 search-field"><label class="visually-hidden" for="search">Buscar por nome ou e-mail</label><input type="search" class="form-control" id="search" name="q" value="<?= e($q) ?>" placeholder="Buscar nome ou e-mail"><button class="btn btn-outline-primary">Buscar</button></form></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Nome / e-mail</th><th>Perfil</th><th>Unidades</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($people as $p): ?><tr><td><strong><?= e($p['nome']) ?></strong><div class="small text-muted"><?= e($p['email']) ?></div></td><td><?= e(ucfirst($p['perfil'])) ?></td><td><?= e($p['unidades']?:'Sem vínculo') ?></td><td><span class="badge <?= $p['status']==='ativo'?'bg-success-subtle text-success':'bg-secondary-subtle text-secondary' ?>"><?= e(ucfirst($p['status'])) ?></span></td><td><?php if($p['perfil']!=='admin'): ?><a class="btn btn-sm btn-outline-secondary" href="<?= url('/admin/pessoas?editar='.(int)$p['id'].'#person-form') ?>" aria-label="Editar <?= e($p['nome']) ?>">Editar</a><?php else: ?><span class="small text-muted">Gestor</span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$people): ?><tr><td colspan="5" class="table-empty">Nenhum cadastro encontrado. Tente outro nome ou e-mail.</td></tr><?php endif; ?></tbody></table></div><div class="card-body small text-muted">Exibindo até 200 cadastros. Use a busca para localizar uma pessoa.</div></div>
<div class="row g-4"><div class="col-lg-7"><section class="card" id="person-form"><div class="card-header"><?= $editing?'Editar cadastro':'Novo cadastro' ?></div><form class="card-body" method="post" action="<?= url('/admin/pessoas/salvar') ?>"><?= csrf_field() ?><input type="hidden" name="action" value="person"><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><div class="mb-3"><label class="form-label" for="person-name">Nome completo</label><input id="person-name" name="nome" class="form-control" value="<?= e($editing['nome']??'') ?>" maxlength="150" required></div><div class="mb-3"><label class="form-label" for="person-email">E-mail</label><input id="person-email" type="email" name="email" class="form-control" value="<?= e($editing['email']??'') ?>" maxlength="191" required></div><div class="row g-3 mb-3"><div class="col-sm-6"><label class="form-label" for="person-role">Perfil</label><select id="person-role" name="perfil" class="form-select"><option value="aluno">Aluno</option><option value="profissional" <?= ($editing['perfil']??'')==='profissional'?'selected':'' ?>>Profissional</option></select></div><div class="col-sm-6"><label class="form-label" for="person-status">Status</label><select id="person-status" name="status" class="form-select"><option value="ativo">Ativo</option><option value="inativo" <?= ($editing['status']??'')==='inativo'?'selected':'' ?>>Inativo</option></select></div></div><?php if(!$editing): ?><div class="mb-3"><label class="form-label" for="person-password">Senha inicial</label><input id="person-password" type="password" name="senha" minlength="12" maxlength="128" autocomplete="new-password" class="form-control" required><div class="form-text">Mínimo de 12 caracteres.</div></div><?php endif; ?><fieldset class="mb-4"><legend class="form-label">Unidades vinculadas</legend><?php foreach($units as $unit): ?><div class="form-check"><input class="form-check-input" type="checkbox" id="unit-<?= (int)$unit['id'] ?>" name="unidades[]" value="<?= (int)$unit['id'] ?>" <?= in_array($unit['id'],$linked)?'checked':'' ?>><label class="form-check-label" for="unit-<?= (int)$unit['id'] ?>"><?= e($unit['nome']) ?> <?= $unit['status']==='inativo'?'(inativa)':'' ?></label></div><?php endforeach; ?><?php if(!$units): ?><p class="text-muted">Cadastre uma unidade ao lado para vincular pessoas.</p><?php endif; ?></fieldset><div class="d-flex gap-2"><button class="btn btn-primary">Salvar cadastro</button><?php if($editing): ?><a class="btn btn-outline-secondary" href="<?= url('/admin/pessoas') ?>">Cancelar edição</a><?php endif; ?></div></form></section></div>
<div class="col-lg-5"><section class="card"><div class="card-header">Unidades da rede</div><div class="card-body"><?php foreach($units as $unit): ?><details class="history-item"><summary><?= e($unit['nome']) ?> <small class="text-muted">· <?= e($unit['status']) ?></small></summary><form class="mt-3" method="post" action="<?= url('/admin/pessoas/salvar') ?>"><?= csrf_field() ?><input type="hidden" name="action" value="unit"><input type="hidden" name="id" value="<?= (int)$unit['id'] ?>"><label class="form-label" for="unit-name-<?= (int)$unit['id'] ?>">Nome da unidade</label><input class="form-control mb-2" id="unit-name-<?= (int)$unit['id'] ?>" name="nome" maxlength="150" value="<?= e($unit['nome']) ?>" required><label class="form-label" for="unit-status-<?= (int)$unit['id'] ?>">Status da unidade</label><select id="unit-status-<?= (int)$unit['id'] ?>" class="form-select mb-3" name="status"><option value="ativo">Ativa</option><option value="inativo" <?= $unit['status']==='inativo'?'selected':'' ?>>Inativa</option></select><button class="btn btn-sm btn-outline-primary">Salvar unidade</button></form></details><?php endforeach; ?><form class="mt-4" method="post" action="<?= url('/admin/pessoas/salvar') ?>"><?= csrf_field() ?><input type="hidden" name="action" value="unit"><label class="form-label" for="new-unit">Nova unidade</label><input id="new-unit" name="nome" class="form-control mb-3" maxlength="150" placeholder="Ex.: Unidade Centro" required><button class="btn btn-outline-primary">Adicionar unidade</button></form></div></section></div></div>

